window.AUTH=window.AUTH||{};window.AUTH["16-1466"]={"d":"16-1466","id":"2017/16-1466","n":"Janus v. American Federation of State, County, and Municipal Employees, Council 31","briefs":[{"k":"petitioner","label":"Brief of petitioner Mark Janus","date":"2017-11-29","url":"https://www.supremecourt.gov/DocketPDF/16/16-1466/21983/20171129151713407_16-1466%20Janus%20Merits%20Brief%20-%20FINAL.pdf","side":"pet","n":84},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2017-12-06","url":"https://www.supremecourt.gov/DocketPDF/16/16-1466/22919/20171206205129333_16-1466tsacUnitedStates.pdf","side":"us","n":55},{"k":"respondent","label":"Brief of respondents Lisa Madigan and Michael Hoffman","date":"2018-01-12","url":"https://www.supremecourt.gov/DocketPDF/16/16-1466/27675/20180112132733604_161466%20Janus%20v%20AFSCME%20Brief%20of%20Respondents%20Madigan%20and%20Hoffman.pdf","side":"res","n":74},{"k":"respondent","label":"Brief of respondent American Federation of State, County, and Municipal Employees, Council 31","date":"2018-01-12","url":"https://www.supremecourt.gov/DocketPDF/16/16-1466/27640/20180112104519993_Resp%20Merits%20Brief%20Janus%20v%20AFSCME.pdf","side":"res","n":80},{"k":"united-states","label":"Brief amicus curiae of United States Conference of Catholic Bishops","date":"2018-01-19","url":"https://www.supremecourt.gov/DocketPDF/16/16-1466/28406/20180119105844172_16.1466%20bsac%20usccb%20amicus.pdf","side":"us","n":11},{"k":"reply","label":"Reply of petitioner Mark Janus","date":"2018-02-12","url":"https://www.supremecourt.gov/DocketPDF/16/16-1466/35203/20180212165133995_Janus%20v%20AFSCME%2016-1466%20Reply%20Brief%20FINAL.pdf","side":"pet","n":36}],"opinion":null,"tr":true,"items":[{"t":"case","label":"14 Penn Plaza LLC v. Pyett","cite":"556 U.S. 247","y":2009,"id":"2008/07-581","sc":1,"sum":"The Court held that arbitration clauses in employment contracts are enforceable as a matter of federal law.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Abood v. Detroit Bd. of Educ.","cite":"431 U.S. 209","y":1977,"id":"1976/75-1153","sc":1,"ar":16,"sum":"A Michigan statute authorizing union representation of local governmental employees permits an \"agency shop\" arrangement, whereby every employee represented by a union, even though not a union member, must pay to the union, as a condition of employment, a service charge equal in amount to union dues. Appellant teachers filed actions (later consolidated) m Michigan state court against appellee Detroit Board of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"passim","3":"passim","4":"20","5":"passim"}},{"t":"case","label":"AFSCME, Council 31 v. Ill. Dep’t of CMS","cite":"2016 WL 7399614","y":2016,"court":"Ill. App. Ct. Dec. 16","by":{"0":"7, 14"}},{"t":"case","label":"Agency for Int’l Dev. v. All. for Open Soc’y Int’l","cite":"133 S. Ct. 2321","y":2013,"url":"https://www.courtlistener.com/c/S.%20Ct./133/2321/","sc":1,"by":{"0":"62"}},{"t":"case","label":"Agostini v. Felton","cite":"521 U.S. 203","y":1997,"id":"1996/96-552","sc":1,"sum":"The Court held that there was no evidence to support its former presumption that the entrance of public school teachers into parochial schools will inevitably lead to the indoctrination of state-sponsored religion.","sumSrc":"Oyez","by":{"0":"10, 25, 34","1":"29, 30"}},{"t":"case","label":"Alexander v. Gardner-Denver Co.","cite":"415 U.S. 36","y":1974,"id":"1973/72-5847","sc":1,"sum":"An employee's statutory right to trial de novo under Title VII of the Civil Rights Act of 1964 is not foreclosed by prior submission of his claim to final arbitration under the nondiscrimination clause of a collective-bargaining.agreement.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"ALPA v. O’Neill","cite":"499 U.S. 65","y":1991,"id":"1990/89-1493","sc":1,"sum":"After Continental Airlines, Inc., filed a petition for reorganization under Chapter 11 of the Bankruptcy Code, it repudiated its collectivebargaining agreement with petitioner Air Line Pilots Association, International (ALPA). An acrimonious strike ensued, during which Continental hired replacement pilots and reemployed several hundred crossover strikers. Two years into the strike, Continental announced in its …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15, 45"}},{"t":"case","label":"Am. Commc’ns Ass’n v. Douds","cite":"339 U.S. 382","y":1950,"id":"1940-1955/339us382","sc":1,"sum":"Section 9 (h) of the National Labor Relations Act, as amended b3 the Labor Management Relations Act, 1947, which imposes certain restrictions on, and denies the benefits of certain provisions of the National Labor Relations Act to, any labor organization the officers of which have not filed with the National Labor Relations Board the so-called \"non-Communist\" affidavits prescribed by § 9 (h), is valid under the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39, 49","1":"22"}},{"t":"case","label":"Arizona v. Gant","cite":"556 U.S. 332","y":2009,"id":"2008/07-542","sc":1,"sum":"The Court held that police may search a suspect's vehicle after his arrest only if it is reasonable to believe that the arrestee might access the vehicle at the time of the search or that the vehicle contains evidence of the offense of the arrest.","sumSrc":"Oyez","by":{"0":"35","1":"30","3":"56","5":"15"}},{"t":"case","label":"Bd. of Regents v. Southworth","cite":"529 U.S. 217","y":2000,"id":"1999/98-1189","sc":1,"sum":"The Court held that the \"First Amendment permits a public university to charge its students an activity fee used to fund a program to facilitate extracurricular student speech if the program is viewpoint neutral.\" Justice Kennedy wrote for the Court that, \"[w]hen a university requires its students to pay fees to support the extracurricular speech of other students, all in the interest of open discussion, it may not prefer some viewpoints to others.\" Justice David H. Souter, in an opinion joined by Justices John Paul Stevens and Stephen G. Breyer, concurred in the judgment only.","sumSrc":"Oyez","by":{"0":"27, 33","2":"22, 23, 56","3":"49","5":"16"}},{"t":"case","label":"(v) Beck v. Commc’ns Workers","cite":"776 F.2d 1187","y":1985,"url":"https://www.courtlistener.com/c/F.2d/776/1187/","by":{"0":"30, 33"}},{"t":"case","label":"Boy Scouts of Am. v. Dale","cite":"530 U.S. 640","y":2000,"id":"1999/99-699","sc":1,"sum":"The Court held that the Boy Scouts of America banning openly homosexual members was constitutional under the First Amendment.","sumSrc":"Oyez","by":{"0":"2, 19, 54, 59","2":"32","3":"28","5":"5, 12"}},{"t":"case","label":"Branti v. Finkel","cite":"445 U.S. 507","y":1980,"id":"1979/78-1654","sc":1,"sum":"The First and Fourteenth Amendments protect respondents from discharge solely because of their political beliefs.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20","1":"26, 29","2":"33","3":"26","5":"7"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":"21","1":"14"}},{"t":"case","label":"Chicago Teachers Union v. Hudson","cite":"475 U.S. 292","y":1986,"id":"1985/84-1503","sc":1,"sum":"Petitioner Chicago Teachers Union has been the exclusive collectivebargaining representative of the Chicago Board of Education's educational employees since 1967. Approximately 95% of the employees are members of the Union. Until 1982, the members' dues financed the entire cost of the Union's collective bargaining and contract administration, and nonmembers received the benefits of the Union's representation without …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 29, 31","2":"passim","3":"7, 46, 48, 51"}},{"t":"case","label":"Citizens Against Rent Control v. City of Berkeley","cite":"454 U.S. 290","y":1981,"id":"1981/80-737","sc":1,"sum":"The restraint imposed by the ordinance on the right of association and in turn on individual and collective rights of expression plainly contravenes both the right of association and the speech guarantees of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Citizens United v. FEC","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"0":"passim","1":"9, 14, 21, 30, 31, 32","3":"28, 51","5":"17"}},{"t":"case","label":"Civil Serv. Comm’n v. Letter Carriers","cite":"413 U.S. 548","y":1973,"id":"1972/72-634","sc":1,"sum":"Some individual federal employees, an employees' union, and certain local Democratic and Republican political committees filed this action challenging as unconstitutional on its face the prohibition in § 9 (a) of the Hatch Act, 5 U. S. C. § 7324 (a) (2), against federal employees' taking \"an active part in political management or in political campaigns.\" The section defines the phrase as \"those acts of political …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","1":"29","2":"20","3":"3, 24"}},{"t":"case","label":"Connick v. Myers","cite":"461 U.S. 138","y":1983,"id":"1982/81-1251","sc":1,"ar":5,"sum":"The Supreme Court held that speech of public employees is generally only protected when they speak on matters of public concern. Meyers’ speech only dealt with personal and internal office issues. The district court also erred in placing too high of a burden on Connick to show that Meyers’ speech substantially interfered with the operation of the office.","sumSrc":"Oyez","by":{"0":"17, 23, 24","1":"24, 28","2":"passim","3":"2, 17, 18, 21, 23, 32, 38, 41, 45","5":"11"}},{"t":"case","label":"Davenport v. Wash. Educ. Ass’n","cite":"551 U.S. 177","y":2007,"id":"2006/05-1589","sc":1,"sum":"The Court ruled that the First Amendment allows a state to require public-sector unions collecting \"agency-shop\" fees from non-union employees to obtain permission from the employees before using the money for political purposes.","sumSrc":"Oyez","by":{"0":"32","1":"1, 3, 18, 22, 31, 32","3":"6, 48, 58","5":"24, 25"}},{"t":"case","label":"Ellis v. Bhd. of Ry. Clerks","cite":"466 U.S. 435","y":1984,"id":"1983/82-1150","sc":1,"ar":1,"sum":"Section 2, Eleventh of the Railway Labor Act permits a union and an employer to require all employees in the relevant bargaining unit to join the union as a condition of continued employment. The collectivebargaining agreement between respondent national union and an airline required that all of the airline's clerical employees join the union or pay agency fees equal to members' dues. Petitioners, present or former …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12","2":"44","3":"46, 48, 51"}},{"t":"case","label":"Elrod v. Burns","cite":"427 U.S. 347","y":1976,"id":"1975/74-1520","sc":1,"ar":1,"sum":"The judgment is affirmed. Pp. 351-374; 374-375. 509 F. 2d 1133, affirmed. MR. JUSTICE BRENNAN, joined by MR. JUSTICE WHITE and MR. JUSTICE MARSHALL, concluded that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"25, 26","2":"33","3":"26","5":"7, 8"}},{"t":"case","label":"Emporium Capwell Co. v. W. Addition Cmty. Org.","cite":"420 U.S. 50","y":1975,"id":"1974/73-696","sc":1,"sum":"Though national labor policy accords the highest priority to nondiscriminatory emWestern Addition Community Organization et al., also on certiorari to the same court. ployment practices, the NLRA does not protect concerted activity by minority employees to bargain with their employer over issues of employment discrimination, thus bypassing their exclusive bargaining representative.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"FEC v. Wis. Right to Life, Inc.","cite":"551 U.S. 449","y":2007,"id":"2006/06-969","sc":1,"ar":6,"sum":"By a 5-4 vote the Court ruled that BCRA's limitations on political advertising were unconstitutional as they applied to issue ads like WRTL's. Chief Justice John Roberts's majority opinion held that the ads were genuine issue ads, not express political advocacy or its functional equivalent (which Congress can concededly regulate).","sumSrc":"Oyez","by":{"0":"8, 21, 35"}},{"t":"case","label":"First Nat’l Bank of Boston v. Bellotti","cite":"435 U.S. 765","y":1978,"id":"1977/76-1172","sc":1,"ar":20,"sum":"The Court held that the right to attempt to influence the outcomes of elections is one of the primary rights the First Amendment was meant to protect. If this form of speech came from a person rather than a corporation, there would be no question about whether it was protected speech.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Force v. Haines","cite":"17 N.J.L. 385","y":1840,"court":"N.J.","url":"https://www.courtlistener.com/c/N.J.L./17/385/","by":{"0":"51"}},{"t":"case","label":"Ford Motor Co. v. Huffman","cite":"345 U.S. 330","y":1953,"id":"scdb/1952-075","sc":1,"sum":"1. A collective-bargaining agreement whereby an employer, in determining relative seniority of employment among its employees, gives them credit for pre-employment military service, as well as the credit for post-employment military service required by the Selective Training and Service Act bf 1940, is valid-although it. works to the disadvantage of other employees, including those who were employed prior to their …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45, 49"}},{"t":"case","label":"Garrison v. Louisiana","cite":"379 U.S. 64","y":1964,"id":"1964/4","sc":1,"sum":"The Court held that a criminal libel statute can only apply to statements that were made knowing they were false or made with reckless disregard as to their falsity.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Glickman v. Wileman Bros. & Elliot, Inc.","cite":"521 U.S. 457","y":1997,"id":"1996/95-1184","sc":1,"ar":1,"sum":"Exempting its financial regulations from the heightened review standard appropriate in most First Amendment issues, the Court's 5-to-4 decision held that just because the AMAA's economic regulations may indirectly result in the reduction of the complaining parties' advertising budgets, they did not violate their free speech.","sumSrc":"Oyez","by":{"0":"33","1":"13, 14","2":"22, 28–29, 56","3":"49","5":"12, 16"}},{"t":"case","label":"Harris v. Quinn, __ U.S. __","cite":"134 S. Ct. 2618","y":2014,"id":"2013/11-681","sc":1,"sum":"The Court held that the First Amendment prohibits the collection of union dues from home health care providers who do not wish to join a union.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"29, 30, 37, 38, 51, 55","4":"16, 18","5":"passim"}},{"t":"case","label":"Hudgens v. NLRB","cite":"424 U.S. 507","y":1976,"id":"1975/74-773","sc":1,"sum":"When striking members of respondent union picketed in front of their employer's leased store located in petitioner's shopping center, the shopping center's general manager threatened them with arrest for criminal trespass if they did not depart, and they left. The union then filed unfair labor practice charges against petitioner, alleging that the threat constituted interference with rights protected by § 7 of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25","1":"31, 32"}},{"t":"case","label":"Humphrey v. Moore","cite":"375 U.S. 335","y":1964,"id":"1963/17","sc":1,"sum":"A decision of a Joint Conference Committee purported to determine the relative seniority rights of employees of two companies under a collective bargaining contract. Respondent Moore, on behalf of himself and other aggrieved employees of one of the companies, brought this class action in a Kentucky state court for an injunction against the union and the company to prevent the decision of the Committee to dovetail …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47, 49"}},{"t":"case","label":"Hurley v. Irish-Am. Gay, Lesbian & Bisexual Grp.","cite":"515 U.S. 557","y":1995,"id":"1994/94-749","sc":1,"sum":"A unanimous court held that the State Court's ruling to require private citizens who organize a parade to include a group expressing a message that the organizers do not wish to convey violates the First Amendment by making private speech subordinate to the public accommodation requirement.","sumSrc":"Oyez","by":{"0":"19","2":"32","3":"28"}},{"t":"case","label":"Ill. Dep’t of CMS v. AFSCME, Council 31, 33 PERI ¶ 67","cite":"2016 WL 7645201","y":2016,"court":"ILRB Dec. 12","by":{"0":"passim"}},{"t":"case","label":"Johanns v. Livestock Mktg. Ass’n","cite":"544 U.S. 550","y":2005,"id":"2004/03-1164","sc":1,"sum":"The Court held that the fund was for government speech and that therefore the government could not be sued under the First Amendment. The Court pointed to the rule that while compelled funding of private speech raises First Amendment concerns, compelled funding of government speech generally does not.","sumSrc":"Oyez","by":{"0":"33","2":"21, 56","3":"49","5":"16"}},{"t":"case","label":"Kidwell v. Transp. Commc’ns Int’l Union","cite":"946 F.2d 283","y":1991,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/946/283/","by":{"0":"40"}},{"t":"case","label":"Knox v. SEIU, Local 1000","cite":"567 U.S. 298","y":2012,"id":"2011/10-1121","sc":1,"ar":2,"sum":"The Court found that, under the First Amendment, public-sector unions are not permitted to impose a special assessment fee without the consent of the member upon whom it is imposed.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"29, 30, 54","5":"passim"}},{"t":"case","label":"Lehnert v. Ferris Faculty Ass’n","cite":"500 U.S. 507","y":1991,"id":"1990/89-1217","sc":1,"sum":"The judgment is affirmed in part and reversed in part, and the case is remanded. 881 F. 2d 1388, affirmed in part, reversed in part, and remanded. JUSTICE BLACKMUN announced the judgment of the Court and delivered the opinion of the Court with respect to Parts 1,11, III-B, III-C, IV-B (except for the final paragraph), IV-D, IV-E, and IV-F, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11, 26, 27","1":"16, 17, 21","2":"passim","3":"7, 15, 31, 34, 38, 45, 46, 47, 48, 49, 52","5":"14"}},{"t":"case","label":"Litton Fin. Printing v. NLRB","cite":"501 U.S. 190","y":1991,"id":"1990/90-285","sc":1,"sum":"The layoff dispute was not arbitrable.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Locke v. Karass","cite":"555 U.S. 207","y":2009,"id":"2008/07-610","sc":1,"sum":"The Court found that fees paid by union nonmembers which were not used to specifically benefit those nonmembers did not violate the First Amendment.","sumSrc":"Oyez","by":{"0":"26, 27","2":"54, 55","3":"48, 51","5":"14"}},{"t":"case","label":"Machinists v. Street","cite":"367 U.S. 740","y":1961,"id":"1959/4","sc":1,"sum":"The Supreme Court held that the lower court did not need to decide the constitutionality of the union shop agreement. The Court remanded the case with suggestions for possible remedies. Justice William O. Douglas wrote a concurrence noting reservations about the suggested remedies. Justice Charles E. Whitaker concurred in part, but dissented to the suggestion of remedies.","sumSrc":"Oyez","by":{"0":"16, 31, 33, 34","1":"4, 15, 18","2":"3","3":"36","5":"10, 11"}},{"t":"case","label":"McCutcheon v. FEC","cite":"134 S. Ct. 1434","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./134/1434/","sc":1,"by":{"0":"21"}},{"t":"case","label":"Medo Photo Supply Corp. v. NLRB","cite":"321 U.S. 678","y":1944,"id":"scdb/1943-085","sc":1,"sum":"that the Labor Board properly determined that petitioner's negotiations with its employees, its payment of increased wages, and its refusal to bargain with the union constituted unfair labor practices in violation of §§ 8 (1) and (5) of the National Labor Relations Act; and that this determination supported its order directing the cessation of those practices.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 39"}},{"t":"case","label":"Meyer v. Grant","cite":"486 U.S. 414","y":1988,"id":"1987/87-920","sc":1,"sum":"The statutory prohibition against the use of paid circulators abridges appellees' right to engage in political speech in violation of the First and Fourteenth Amendments.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Miller v. ALPA","cite":"108 F.3d 1415","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/108/1415/","by":{"0":"27"}},{"t":"case","label":"Montejo v. Louisiana","cite":"556 U.S. 778","y":2009,"id":"2008/07-1529","sc":1,"sum":"The Court held that after the appointment of an attorney, a defendant does not necessarily need to take additional steps to accept the appointment in order to secure the protections of the Sixth Amendment.","sumSrc":"Oyez","by":{"0":"10, 32"}},{"t":"case","label":"NAACP v. Claiborne Hardware Co.","cite":"458 U.S. 886","y":1982,"id":"1981/81-202","sc":1,"sum":"The Court held that the NAACP's nonviolent protest was protected by the First Amendment.","sumSrc":"Oyez","by":{"0":"57"}},{"t":"case","label":"Neal v. Newspaper Holdings, Inc.","cite":"349 U.S. 363","y":2003,"court":"7th Cir.","url":"https://supreme.justia.com/cases/federal/us/349/363/","sc":1,"by":{"0":"47"}},{"t":"case","label":"NLRB v. Allis-Chalmers Mfg. Co.","cite":"388 U.S. 175","y":1967,"id":"1966/216","sc":1,"sum":"Lawful economic strikes were called at two of respondent AllisChalmers' plants in accordance with duly authorized union procedures by the locals of the union representing the employees. Some union members crossed picket lines and worked during the strikes. After the strikes were over the locals brought proceedings against these members, imposed fines of $20 to $100, and sued in state courts to collect the fines. The …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 38, 48, 49","1":"2"}},{"t":"case","label":"NLRB v. Ins. Agents’ Int’l Union","cite":"361 U.S. 477","y":1967,"id":"1959/15","sc":1,"sum":"Such tactics would not support a finding by the Board that the union had failed to bargain in good faith as required by § 8 (b) (3). Pp. 478-500. (1) The basic premise of the duty of collective bargaining required in the Act is that it is a process in which the parties deal with each other in a serious, good-faith desire to reach agreement and to enter into a contract ordering their industrial relationship. Congress …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"60, 61"}},{"t":"case","label":"N.Y. State Bd. of Elections v. Lopez Torres","cite":"552 U.S. 196","y":2008,"id":"2007/06-766","sc":1,"sum":"The Court reversed the Second Circuit, finding that the election scheme did not implicate Lopez Torres' rights under the First Amendment.","sumSrc":"Oyez","by":{"0":"57"}},{"t":"case","label":"N.Y. Times v. Sullivan","cite":"376 U.S. 254","y":1964,"id":"1963/39","sc":1,"sum":"The Court held that the First Amendment protects freedom of speech and freedom of the press, even about the conduct of politicians, unless the statements are made with actual malice.","sumSrc":"Oyez","by":{"0":"59","1":"14"}},{"t":"case","label":"O’Hare Truck Serv., Inc. v. City of Northlake","cite":"518 U.S. 712","y":1996,"id":"1995/95-191","sc":1,"sum":"The Court held, in an opinion by Justice Anthony Kennedy, that independent contractors, such as O'Hare Truck Service, are entitled to the same First Amendment protections as those afforded to government employees.","sumSrc":"Oyez","by":{"0":"23, 52","2":"33","3":"25"}},{"t":"case","label":"Payne v. Tennessee","cite":"501 U.S. 808","y":1991,"id":"1990/90-5721","sc":1,"sum":"The Court reasoned that since \"[v]irtually no limits are placed on the relevant mitigating evidence a capital defendant may introduce concerning his own circumstances,\" the prosecution must be allowed to submit similar counter evidence.","sumSrc":"Oyez","by":{"0":"32, 35","2":"54","3":"47"}},{"t":"case","label":"Pickering v. Bd. of Educ.","cite":"391 U.S. 563","y":1968,"id":"1967/510","sc":1,"ar":11,"sum":"Justice Thurgood Marshall wrote the 8-1 majority opinion holding that Pickering’s dismissal violated his First Amendment right to free speech. The Supreme Court noted that similar speech is not protected if it contains false statements knowingly or recklessly made. There was no evidence that Pickering’s statements were knowingly false or reckless.","sumSrc":"Oyez","by":{"0":"22, 23, 24, 25","1":"9, 10, 23, 27","2":"passim","3":"14, 15, 18, 20, 21, 22, 23, 24, 25, 44, 56","5":"10, 11, 17"}},{"t":"case","label":"Pocatello Educ. Ass’n v. Heideman","cite":"504 F.3d 1053","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/504/1053/","by":{"0":"42"}},{"t":"case","label":"Ry. Emps’ Dep’t v. Hanson","cite":"351 U.S. 225","y":1956,"id":"1955/451","sc":1,"sum":"Claiming that a \"union shop\" agreement between an interstate railroad and unions of its employees made pursuant to § 2, Eleventh, of the Railway Labor Act, which expressly authorizes such agreements notwithstanding any state law, violated the First and Fifth Amendments of the Federal Constitution and the \"right to work\" provision of the Nebraska Constitution, nonunion employees of the railroad sued in a Nebraska …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 34, 56","1":"4, 14, 18","2":"3"}},{"t":"case","label":"Riley v. Nat’l Fed’n of the Blind","cite":"487 U.S. 781","y":1988,"id":"1987/87-328","sc":1,"ar":1,"sum":"The North Carolina Charitable Solicitations Act defines the prima facie \"reasonable fee\" that a professional fundraiser may charge according to a three-tiered schedule. A fee up to 20% of receipts collected is deemed reasonable. A fee between 20% and 35% is deemed unreasonable upon a showing that the solicitation at issue did not involve the \"dissemination of information, discussion, or advocacy relating to public …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 20, 52","1":"12","2":"26","3":"28"}},{"t":"case","label":"Roberts v. U.S. Jaycees","cite":"468 U.S. 609","y":1984,"id":"1983/83-724","sc":1,"sum":"The Court held that the Jaycees chapters lacked \"the distinctive characteristics that might afford constitutional protection to the decision of its members to exclude women.\" The Court reasoned that making women full members would not impose any serious burdens on the male members' freedom of expressive association.","sumSrc":"Oyez","by":{"0":"2, 3, 19","2":"32, 35–36","4":"19"}},{"t":"case","label":"Rutan v. Republican Party","cite":"497 U.S. 62","y":1990,"id":"1989/88-1872","sc":1,"sum":"In a 5-to-4 decision, the Court held that Governor Thompson's practices amounted to an unconstitutional patronage system. The Court found that employees would feel \"a significant obligation to support political positions held by their superiors\" in lieu of their true beliefs in order to progress up the career ladder.","sumSrc":"Oyez","by":{"0":"2, 20, 23, 56","1":"25, 26","2":"32, 33","3":"25, 26, 30","5":"7"}},{"t":"case","label":"Scheffer v. Civil Serv. Emps. Ass’n","cite":"610 F.3d 782","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/610/782/","by":{"0":"27"}},{"t":"case","label":"Schneider Moving & Storage Co. v. Robbins","cite":"466 U.S. 364","y":1984,"id":"1983/82-1860","sc":1,"sum":"Respondents may seek judicial enforcement of the trust terms against petitioners without first submitting to arbitration an underlying dispute over the meaning of a term in the collective-bargaining agreements.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"60"}},{"t":"case","label":"Snyder v. Phelps","cite":"131 S. Ct. 1207","y":2011,"id":"2010/09-751","sc":1,"sum":"The Court held that the Westboro Baptist Church was protected under the First Amendment while picketing a military funeral.","sumSrc":"Oyez","by":{"0":"17","1":"14","2":"50"}},{"t":"case","label":"State Emp. Bargaining Agent Coal. v. Rowland","cite":"718 F.3d 126","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/718/126/","by":{"0":"45"}},{"t":"case","label":"Steele v. Louisville & Nashville Ry.","cite":"323 U.S. 192","y":1944,"id":"scdb/1944-008","sc":1,"by":{"0":"38"}},{"t":"case","label":"Sweeney v. Pence","cite":"767 F.3d 654","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/767/654/","by":{"0":"38, 39"}},{"t":"case","label":"Teamsters, Local 391 v. Terry","cite":"494 U.S. 558","y":1990,"id":"1989/88-1719","sc":1,"sum":"The judgment is affirmed. 863 F. 2d 334, affirmed. JUSTICE MARSHALL delivered the opinion of the Court with respect to Parts 1, 11, III-B, and IV, concluding that the Seventh Amendment entitles respondents to a jury trial. Pp. 563-564, 570-574.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"United States v. Associated Press","cite":"52 F. Supp. 362","y":1943,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./52/362/","by":{"0":"59"}},{"t":"case","label":"United States v. NTEU","cite":"513 U.S. 454","y":1995,"id":"1994/93-1170","sc":1,"sum":"In a 6 to 3 decision delivered by Justice John Paul Stevens, the Court declared that a flat ban violated free-speech rights. Concerns about impropriety do not apply if there is no link between a government employee's job and \"the subject matter of the expression or the character of the payor.\".","sumSrc":"Oyez","by":{"0":"24","1":"24, 28","2":"27"}},{"t":"case","label":"United States v. United Foods, Inc.","cite":"533 U.S. 405","y":2001,"id":"2000/00-276","sc":1,"sum":"The Court held that the assessment requirement violates the First Amendment.","sumSrc":"Oyez","by":{"0":"16, 17","1":"5, 12, 13, 22, 31","2":"passim","3":"29, 49","5":"5, 6, 13, 22"}},{"t":"case","label":"Vaca v. Sipes","cite":"386 U.S. 171","y":1967,"id":"1966/114","sc":1,"sum":"Petitioners, union officials, were sued in a state court by a union member who alleged wrongful discharge by his employer in violation of the collective bargaining agreement and the union's arbitrary refusal to take his grievance to arbitration under the fifth and final step of the bargaining agreement's grievance procedures. The employee, whose duties required strenuous activity, was discharged on the ground of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46, 50","2":"39, 41–42, 45"}},{"t":"case","label":"Vienna Sch. Dist. No. 55 v. IELRB","cite":"515 N.E.2d 476","y":1987,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/N.E.2d/515/476/","by":{"0":"5"}},{"t":"case","label":"W. Va. State Bd. of Educ. v. Barnette","cite":"319 U.S. 624","y":1943,"id":"1940-1955/319us624","sc":1,"sum":"The Court found that a West Virginia statute requiring students and teachers say the Pledge of Allegiance, under threat of expulsion and delinquency charges, was unconstitutional.","sumSrc":"Oyez","by":{"0":"50","1":"14","2":"49","3":"28"}},{"t":"case","label":"Wis. Educ. Ass’n Council v. Walker","cite":"705 F.3d 640","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/705/640/","by":{"0":"42"}},{"t":"case","label":"Wooley v. Maynard","cite":"430 U.S. 705","y":1977,"id":"1976/75-1453","sc":1,"ar":1,"sum":"In a 6-to-3 decision, the Court held that New Hampshire could not constitutionally require citizens to display the state motto upon their vehicle license plates.","sumSrc":"Oyez","by":{"0":"2, 20","2":"49–50","3":"28","5":"5"}},{"t":"case","label":"Ysursa v. Pocatello Educ. Ass’n","cite":"555 U.S. 353","y":2009,"id":"2008/07-869","sc":1,"sum":"The Court found that provisions of Idaho's Voluntary Contributions Act which prohibit payroll deductions for \"political activities\" did not violate the First Amendment when applied to local government employees.","sumSrc":"Oyez","by":{"0":"42","1":"21"}},{"t":"case","label":"Zoeller v. Sweeney","cite":"19 N.E.3d 749","y":2014,"court":"Ind.","url":"https://www.courtlistener.com/c/N.E.3d/19/749/","by":{"0":"39"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"passim","1":"passim","3":"passim","5":"passim"}},{"t":"usc","label":"2 U.S.C. § 1602","url":"https://www.law.cornell.edu/uscode/text/2/1602","subs":["(8)(A)"],"by":{"0":"12"}},{"t":"usc","label":"5 U.S.C. § 7102","url":"https://www.law.cornell.edu/uscode/text/5/7102","stext":{"head":"§7102. Employees' rights","paras":[[0,"Each employee shall have the right to form, join, or assist any labor organization, or to refrain from any such activity, freely and without fear of penalty or reprisal, and each employee shall be protected in the exercise of such right. Except as otherwise provided under this chapter, such right includes the right—"],[1,"(1) to act for a labor organization in the capacity of a representative and the right, in that capacity, to present the views of the labor organization to heads of agencies and other officials of the executive branch of the Government, the Congress, or other appropriate authorities, and"],[1,"(2) to engage in collective bargaining with respect to conditions of employment through representatives chosen by employees under this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7102?type=usc&year=mostrecent&link-type=html"},"head":"§7102. Employees' rights","tname":"Government Organization and Employees","by":{"0":"37, 40","1":"20"}},{"t":"usc","label":"5 U.S.C. § 7115","url":"https://www.law.cornell.edu/uscode/text/5/7115","subs":["(a)"],"by":{"0":"42"}},{"t":"usc","label":"5 U.S.C. § 7131","url":"https://www.law.cornell.edu/uscode/text/5/7131","stext":{"head":"§7131. Official time","paras":[[0,"(a) Any employee representing an exclusive representative in the negotiation of a collective bargaining agreement under this chapter shall be authorized official time for such purposes, including attendance at impasse proceeding, during the time the employee otherwise would be in a duty status. The number of employees for whom official time is authorized under this subsection shall not exceed the number of individuals designated as representing the agency for such purposes."],[0,"(b) Any activities performed by any employee relating to the internal business of a labor organization (including the solicitation of membership, elections of labor organization officials, and collection of dues) shall be performed during the time the employee is in a non-duty status."],[0,"(c) Except as provided in subsection (a) of this section, the Authority shall determine whether any employee participating for, or on behalf of, a labor organization in any phase of proceedings before the Authority shall be authorized official time for such purpose during the time the employee otherwise would be in a duty status."],[0,"(d) Except as provided in the preceding subsections of this section—"],[1,"(1) any employee representing an exclusive representative, or"],[1,"(2) in connection with any other matter covered by this chapter, any employee in an appropriate unit represented by an exclusive representative,"],[0,"shall be granted official time in any amount the agency and the exclusive representative involved agree to be reasonable, necessary, and in the public interest."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7131?type=usc&year=mostrecent&link-type=html"},"head":"§7131. Official time","tname":"Government Organization and Employees","by":{"0":"39","3":"37"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"39 U.S.C. § 1209","url":"https://www.law.cornell.edu/uscode/text/39/1209","subs":["(c)"],"by":{"0":"37"}},{"t":"case","label":"Amalgamated Food Emps. Union v. Logan Valley Plaza, Inc.","cite":"391 U.S. 308","y":1968,"id":"1967/478","sc":1,"sum":"Respondent Weis Markets owns and operates a supermarket in a large shopping center complex owned by respondent Logan Valley Plaza. In front of Weis' building is a covered porch and a parcel pickup zone. Members of petitioner union picketed Weis' store, confining the picketing almost entirely to the parcel pickup zone and the portion of the parking area adjacent thereto. The picket-' ing was peaceful with some …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Arizona Free Enter. Club’s Freedom Club PAC v. Bennett","cite":"564 U.S. 721","y":2011,"id":"2010/10-238","sc":1,"sum":"The Court held that the Arizona campaign finance law linking public financing for candidates to the amount spent by their opponents violated the First Amendment's protection of political speech.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"City of Madison Joint Sch. Dist. No. 8 v. Wisconsin Emp’t Relations Comm’n","cite":"429 U.S. 167","y":1976,"id":"1976/75-946","sc":1,"ar":1,"sum":"During the course of a regularly scheduled, open meeting of appellant Board of Education, public discussion turned to currently pending labor negotiations between the board and the teachers' union. One speaker was a nonunion teacher who, over union objection, addressed one topic of the pending negotiations, namely, the union's demand for a \"fair share\" clause, which would require all teachers (whether union members …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21","2":"25, 49","3":"27"}},{"t":"case","label":"Communications Workers of Am. v. Beck","cite":"487 U.S. 735","y":1988,"id":"1987/86-637","sc":1,"sum":"Section 8(a)(3) of the National Labor Relations Act (NLRA) permits an employer and a union to enter into an agreement requiring all employees in the bargaining unit to pay union dues as a condition of continued employment, whether or not the employees become union members. Petitioner Communications Workers of America (CWA) entered into a collective-bargaining agreement that contains a union-security clause under …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33","2":"37, 42","3":"5, 36, 58"}},{"t":"case","label":"Dickerson v. United States","cite":"530 U.S. 428","y":2000,"id":"1999/99-5525","sc":1,"sum":"The Court held that Congress cannot legislatively overrule Miranda v. Arizona.","sumSrc":"Oyez","by":{"1":"30","2":"51","3":"47"}},{"t":"case","label":"Garcetti v. Ceballos","cite":"547 U.S. 410","y":2006,"id":"2005/04-473","sc":1,"ar":6,"sum":"In a 5-to-4 decision authored by Justice Anthony Kennedy, the Supreme Court held that speech by a public official is only protected if it is engaged in as a private citizen, not if it is expressed as part of the official's public duties.","sumSrc":"Oyez","by":{"1":"24, 26, 27","2":"passim","3":"14, 18, 19, 21, 22, 23, 24, 25, 31, 33, 39, 40, 41-42","5":"2, 15"}},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"134 S. Ct. 2398","y":2014,"id":"2013/13-317","sc":1,"sum":"The Court held that there is no undue burden in allowing defendants in securities fraud cases from presenting evidence regarding the alleged impact of the misinformation on stock prices.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Keller v. State Bar","cite":"496 U.S. 1","y":1990,"id":"1989/88-1905","sc":1,"ar":2,"sum":"Respondent State Bar of California (State Bar) is an \"integrated bar\"i. e., an association of attorneys in which membership and dues are required as a condition of practicing law-created under state law to regulate the State's legal profession. In fulfilling its broad statutory mission to \"promote the improvement of the administration of justice,\" the Bar uses its membership dues for self-regulatory functions, such …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15","2":"passim","3":"48, 49","5":"16"}},{"t":"case","label":"Lane v. Franks","cite":"134 S. Ct. 2369","y":2014,"id":"2013/13-483","sc":1,"sum":"The Court held that a public employee's truthful testimony under subpoena in a trial is citizen speech and thus cannot be used to terminate the employee.","sumSrc":"Oyez","by":{"1":"23, 24, 26, 27, 28","2":"17","3":"18","5":"10, 12"}},{"t":"case","label":"Lincoln Fed. Labor Union No. 19129 v. Northwest- ern Iron & Metal Co.","cite":"335 U.S. 525","y":1949,"id":"1940-1955/335us525","sc":1,"sum":"The Court held that the Due Process Clause did not prevent states from prohibiting contracts to engage in conduct banned by valid state laws. The liberty of persons to make contracts did not prevent Nebraska from enacting anti-discrimination statutes.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Lloyd Corp. v. Tanner","cite":"407 U.S. 551","y":1972,"id":"1971/71-492","sc":1,"sum":"The Court reversed the Ninth Circuit and held that Tanner was not entitled to distribute handbills within Lloyd Center.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Ring v. Arizona","cite":"536 U.S. 584","y":2002,"id":"2001/01-488","sc":1,"sum":"The Court held that, because Arizona's enumerated aggravating factors operates as \"the functional equivalent of an element of a greater offense,\" the Sixth Amendment requires that they be found by a jury.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Rumsfeld v. Forum for Academic & Institutional Rights, Inc.","cite":"547 U.S. 47","y":2006,"id":"2005/04-1152","sc":1,"sum":"The Supreme Court, in a unanimous opinion written by Chief Justice John Roberts, held that the Solomon Amendment regulated conduct, not speech, and was therefore constitutional. Including military recruiters in receptions and interviews does not necessarily indicate university endorsement of the recruiters, so requiring their inclusion does not constitute compelled speech in violation of the First Amendment.","sumSrc":"Oyez","by":{"1":"12","2":"50","3":"29"}},{"t":"case","label":"Shelby Cnty. v. Holder","cite":"133 S. Ct. 2612","y":2013,"id":"2012/12-96","sc":1,"sum":"The Court found that Section 4 of the Voting Rights Act was unconstitutional.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"State v. American Fed’n of State, Cnty., & Mun. Emps. Council 31","cite":"51 N.E.3d 738","y":2016,"court":"Ill.","url":"https://www.courtlistener.com/c/N.E.3d/51/738/","by":{"1":"16","5":"6"}},{"t":"case","label":"Williams-Yulee v. Florida Bar","cite":"135 S. Ct. 1656","y":2015,"id":"2014/13-1499","sc":1,"sum":"The Court held that a rule prohibiting judicial candidates from personally soliciting campaign funds does not violate the First Amendment.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"usc","label":"5 U.S.C. § 7321","url":"https://www.law.cornell.edu/uscode/text/5/7321","stext":{"head":"§7321. Political participation","paras":[[0,"It is the policy of the Congress that employees should be encouraged to exercise fully, freely, and without fear of penalty or reprisal, and to the extent not expressly prohibited by law, their right to participate or to refrain from participating in the political processes of the Nation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7321?type=usc&year=mostrecent&link-type=html"},"head":"§7321. Political participation","tname":"Government Organization and Employees","by":{"1":"29","3":"3, 24"}},{"t":"usc","label":"29 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/29/151","stext":{"head":"§151. Findings and declaration of policy","paras":[[0,"The denial by some employers of the right of employees to organize and the refusal by some employers to accept the procedure of collective bargaining lead to strikes and other forms of industrial strife or unrest, which have the intent or the necessary effect of burdening or obstructing commerce by (a) impairing the efficiency, safety, or operation of the instrumentalities of commerce; (b) occurring in the current of commerce; (c) materially affecting, restraining, or controlling the flow of raw materials or manufactured or processed goods from or into the channels of commerce, or the prices of such materials or goods in commerce; or (d) causing diminution of employment and wages in such volume as substantially to impair or disrupt the market for goods flowing from or into the channels of commerce."],[0,"The inequality of bargaining power between employees who do not possess full freedom of association or actual liberty of contract, and employers who are organized in the corporate or other forms of ownership association substantially burdens and affects the flow of commerce, and tends to aggravate recurrent business depressions, by depressing wage rates and the purchasing power of wage earners in industry and by preventing the stabilization of competitive wage rates and working conditions within and between industries."],[0,"Experience has proved that protection by law of the right of employees to organize and bargain collectively safeguards commerce from injury, impairment, or interruption, and promotes the flow of commerce by removing certain recognized sources of industrial strife and unrest, by encouraging practices fundamental to the friendly adjustment of industrial disputes arising out of differences as to wages, hours, or other working conditions, and by restoring equality of bargaining power between employers and employees."],[0,"Experience has further demonstrated that certain practices by some labor organizations, their officers, and members have the intent or the necessary effect of burdening or obstructing commerce by preventing the free flow of goods in such commerce through strikes and other forms of industrial unrest or through concerted activities which impair the interest of the public in the free flow of such commerce. The elimination of such practices is a necessary condition to the assurance of the rights herein guaranteed."],[0,"It is hereby declared to be the policy of the United States to eliminate the causes of certain substantial obstructions to the free flow of commerce and to mitigate and eliminate these obstructions when they have occurred by encouraging the practice and procedure of collective bargaining and by protecting the exercise by workers of full freedom of association, self-organization, and designation of representatives of their own choosing, for the purpose of negotiating the terms and conditions of their employment or other mutual aid or protection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/151?type=usc&year=mostrecent&link-type=html"},"head":"§151. Findings and declaration of policy","tname":"Labor","by":{"1":"2","3":"5, 6"}},{"t":"usc","label":"29 U.S.C. § 152","url":"https://www.law.cornell.edu/uscode/text/29/152","subs":["(2)"],"stext":{"head":"§152. Definitions","paras":[[0,"When used in this subchapter—"],[1,"(1) The term \"person\" includes one or more individuals, labor organizations, partnerships, associations, corporations, legal representatives, trustees, trustees in cases under title 11, or receivers."],[1,"(2) The term \"employer\" includes any person acting as an agent of an employer, directly or indirectly, but shall not include the United States or any wholly owned Government corporation, or any Federal Reserve Bank, or any State or political subdivision thereof, or any person subject to the Railway Labor Act [45 U.S.C. 151 et seq.], as amended from time to time, or any labor organization (other than when acting as an employer), or anyone acting in the capacity of officer or agent of such labor organization."],[1,"(3) The term \"employee\" shall include any employee, and shall not be limited to the employees of a particular employer, unless this subchapter explicitly states otherwise, and shall include any individual whose work has ceased as a consequence of, or in connection with, any current labor dispute or because of any unfair labor practice, and who has not obtained any other regular and substantially equivalent employment, but shall not include any individual employed as an agricultural laborer, or in the domestic service of any family or person at his home, or any individual employed by his parent or spouse, or any individual having the status of an independent contractor, or any individual employed as a supervisor, or any individual employed by an employer subject to the Railway Labor Act [45 U.S.C. 151 et seq.], as amended from time to time, or by any other person who is not an employer as herein defined."],[1,"(4) The term \"representatives\" includes any individual or labor organization."],[1,"(5) The term \"labor organization\" means any organization of any kind, or any agency or employee representation committee or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours of employment, or conditions of work."],[1,"(6) The term \"commerce\" means trade, traffic, commerce, transportation, or communication among the several States, or between the District of Columbia or any Territory of the United States and any State or other Territory, or between any foreign country and any State, Territory, or the District of Columbia, or within the District of Columbia or any Territory, or between points in the same State but through any other State or any Territory or the District of Columbia or any foreign country."],[1,"(7) The term \"affecting commerce\" means in commerce, or burdening or obstructing commerce or the free flow of commerce, or having led or tending to lead to a labor dispute burdening or obstructing commerce or the free flow of commerce."],[1,"(8) The term \"unfair labor practice\" means any unfair labor practice listed in section 158 of this title."],[1,"(9) The term \"labor dispute\" includes any controversy concerning terms, tenure or conditions of employment, or concerning the association or representation of persons in negotiating, fixing, maintaining, changing, or seeking to arrange terms or conditions of employment, regardless of whether the disputants stand in the proximate relation of employer and employee."],[1,"(10) The term \"National Labor Relations Board\" means the National Labor Relations Board provided for in section 153 of this title."],[1,"(11) The term \"supervisor\" means any individual having authority, in the interest of the employer, to hire, transfer, suspend, lay off, recall, promote, discharge, assign, reward, or discipline other employees, or responsibly to direct them, or to adjust their grievances, or effectively to recommend such action, if in connection with the foregoing the exercise of such authority is not of a merely routine or clerical nature, but requires the use of independent judgment."],[1,"(12) The term \"professional employee\" means—"],[2,"(a) any employee engaged in work (i) predominantly intellectual and varied in character as opposed to routine mental, manual, mechanical, or physical work; (ii) involving the consistent exercise of discretion and judgment in its performance; (iii) of such a character that the output produced or the result accomplished cannot be standardized in relation to a given period of time; (iv) requiring knowledge of an advanced type in a field of science or learning customarily acquired by a prolonged course of specialized intellectual instruction and study in an institution of higher learning or a hospital, as distinguished from a general academic education or from an apprenticeship or from training in the performance of routine mental, manual, or physical processes; or"],[2,"(b) any employee, who (i) has completed the courses of specialized intellectual instruction and study described in clause (iv) of paragraph (a), and (ii) is performing related work under the supervision of a professional person to qualify himself to become a professional employee as defined in paragraph (a)."],[1,"(13) In determining whether any person is acting as an \"agent\" of another person so as to make such other person responsible for his acts, the question of whether the specific acts performed were actually authorized or subsequently ratified shall not be controlling."],[1,"(14) The term \"health care institution\" shall include any hospital, convalescent hospital, health maintenance organization, health clinic, nursing home, extended care facility, or other institution devoted to the care of sick, infirm, or aged person.1"]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/152?type=usc&year=mostrecent&link-type=html"},"head":"§152. Definitions","tname":"Labor","by":{"1":"2","2":"37","3":"6"}},{"t":"usc","label":"29 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/29/158","subs":["(a)(3)","(a)(2)"],"stext":{"head":"§158. Unfair labor practices","paras":[[0,"(a) Unfair labor practices by employer"],[0,"It shall be an unfair labor practice for an employer—"],[1,"(1) to interfere with, restrain, or coerce employees in the exercise of the rights guaranteed in section 157 of this title;"],[1,"(2) to dominate or interfere with the formation or administration of any labor organization or contribute financial or other support to it: Provided, That subject to rules and regulations made and published by the Board pursuant to section 156 of this title, an employer shall not be prohibited from permitting employees to confer with him during working hours without loss of time or pay;"],[1,"(3) by discrimination in regard to hire or tenure of employment or any term or condition of employment to encourage or discourage membership in any labor organization: Provided, That nothing in this subchapter, or in any other statute of the United States, shall preclude an employer from making an agreement with a labor organization (not established, maintained, or assisted by any action defined in this subsection as an unfair labor practice) to require as a condition of employment membership therein on or after the thirtieth day following the beginning of such employment or the effective date of such agreement, whichever is the later, (i) if such labor organization is the representative of the employees as provided in section 159(a) of this title, in the appropriate collective-bargaining unit covered by such agreement when made, and (ii) unless following an election held as provided in section 159(e) of this title within one year preceding the effective date of such agreement, the Board shall have certified that at least a majority of the employees eligible to vote in such election have voted to rescind the authority of such labor organization to make such an agreement: Provided further, That no employer shall justify any discrimination against an employee for nonmembership in a labor organization (A) if he has reasonable grounds for believing that such membership was not available to the employee on the same terms and conditions generally applicable to other members, or (B) if he has reasonable grounds for believing that membership was denied or terminated for reasons other than the failure of the employee to tender the periodic dues and the initiation fees uniformly required as a condition of acquiring or retaining membership;"],[1,"(4) to discharge or otherwise discriminate against an employee because he has filed charges or given testimony under this subchapter;"],[1,"(5) to refuse to bargain collectively with the representatives of his employees, subject to the provisions of section 159(a) of this title."],[0,"(b) Unfair labor practices by labor organization"],[0,"It shall be an unfair labor practice for a labor organization or its agents—"],[1,"(1) to restrain or coerce (A) employees in the exercise of the rights guaranteed in section 157 of this title: Provided, That this paragraph shall not impair the right of a labor organization to prescribe its own rules with respect to the acquisition or retention of membership therein; or (B) an employer in the selection of his representatives for the purposes of collective bargaining or the adjustment of grievances;"],[1,"(2) to cause or attempt to cause an employer to discriminate against an employee in violation of subsection (a)(3) or to discriminate against an employee with respect to whom membership in such organization has been denied or terminated on some ground other than his failure to tender the periodic dues and the initiation fees uniformly required as a condition of acquiring or retaining membership;"],[1,"(3) to refuse to bargain collectively with an employer, provided it is the representative of his employees subject to the provisions of section 159(a) of this title;"],[1,"(4)(i) to engage in, or to induce or encourage any individual employed by any person engaged in commerce or in an industry affecting commerce to engage in, a strike or a refusal in the course of his employment to use, manufacture, process, transport, or otherwise handle or work on any goods, articles, materials, or commodities or to perform any services; or (ii) to threaten, coerce, or restrain any person engaged in commerce or in an industry affecting commerce, where in either case an object thereof is—"],[2,"(A) forcing or requiring any employer or self-employed person to join any labor or employer organization or to enter into any agreement which is prohibited by subsection (e);"],[2,"(B) forcing or requiring any person to cease using, selling, handling, transporting, or otherwise dealing in the products of any other producer, processor, or manufacturer, or to cease doing business with any other person, or forcing or requiring any other employer to recognize or bargain with a labor organization as the representative of his employees unless such labor organization has been certified as the representative of such employees under the provisions of section 159 of this title: Provided, That nothing contained in this clause (B) shall be construed to make unlawful, where not otherwise unlawful, any primary strike or primary picketing;"],[2,"(C) forcing or requiring any employer to recognize or bargain with a particular labor organization as the representative of his employees if another labor organization has been certified as the representative of such employees under the provisions of section 159 of this title;"],[2,"(D) forcing or requiring any employer to assign particular work to employees in a particular labor organization or in a particular trade, craft, or class rather than to employees in another labor organization or in another trade, craft, or class, unless such employer is failing to conform to an order or certification of the Board determining the bargaining representative for employees performing such work:"],[1,"Provided, That nothing contained in this subsection shall be construed to make unlawful a refusal by any person to enter upon the premises of any employer (other than his own employer), if the employees of such employer are engaged in a strike ratified or approved by a representative of such employees whom such employer is required to recognize under this subchapter: Provided further, That for the purposes of this paragraph (4) only, nothing contained in such paragraph shall be construed to prohibit publicity, other than picketing, for the purpose of truthfully advising the public, including consumers and members of a labor organization, that a product or products are produced by an employer with whom the labor organization has a primary dispute and are distributed by another employer, as long as such publicity does not have an effect of inducing any individual employed by any person other than the primary employer in the course of his employment to refuse to pick up, deliver, or transport any goods, or not to perform any services, at the establishment of the employer engaged in such distribution;"],[1,"(5) to require of employees covered by an agreement authorized under subsection (a)(3) the payment, as a condition precedent to becoming a member of such organization, of a fee in an amount which the Board finds excessive or discriminatory under all the circumstances. In making such a finding, the Board shall consider, among other relevant factors, the practices and customs of labor organizations in the particular industry, and the wages currently paid to the employees affected;"],[1,"(6) to cause or attempt to cause an employer to pay or deliver or agree to pay or deliver any money or other thing of value, in the nature of an exaction, for services which are not performed or not to be performed; and"],[1,"(7) to picket or cause to be picketed, or threaten to picket or cause to be picketed, any employer where an object thereof is forcing or requiring an employer to recognize or bargain with a labor organization as the representative of his employees, or forcing or requiring the employees of an employer to accept or select such labor organization as their collective bargaining representative, unless such labor organization is currently certified as the representative of such employees:"],[2,"(A) where the employer has lawfully recognized in accordance with this subchapter any other labor organization and a question concerning representation may not appropriately be raised under section 159(c) of this title,"],[2,"(B) where within the preceding twelve months a valid election under section 159(c) of this title has been conducted, or"],[2,"(C) where such picketing has been conducted without a petition under section 159(c) of this title being filed within a reasonable period of time not to exceed thirty days from the commencement of such picketing: Provided, That when such a petition has been filed the Board shall forthwith, without regard to the provisions of section 159(c)(1) of this title or the absence of a showing of a substantial interest on the part of the labor organization, direct an election in such unit as the Board finds to be appropriate and shall certify the results thereof: Provided further, That nothing in this subparagraph (C) shall be construed to prohibit any picketing or other publicity for the purpose of truthfully advising the public (including consumers) that an employer does not employ members of, or have a contract with, a labor organization, unless an effect of such picketing is to induce any individual employed by any other person in the course of his employment, not to pick up, deliver or transport any goods or not to perform any services."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/158?type=usc&year=mostrecent&link-type=html"},"head":"§158. Unfair labor practices","tname":"Labor","by":{"1":"1, 33","2":"37","5":"3"}},{"t":"usc","label":"29 U.S.C. § 164","url":"https://www.law.cornell.edu/uscode/text/29/164","subs":["(b)"],"stext":{"head":"§164. Construction of provisions","paras":[[0,"(a) Supervisors as union members"],[0,"Nothing herein shall prohibit any individual employed as a supervisor from becoming or remaining a member of a labor organization, but no employer subject to this subchapter shall be compelled to deem individuals defined herein as supervisors as employees for the purpose of any law, either national or local, relating to collective bargaining."],[0,"(b) Agreements requiring union membership in violation of State law"],[0,"Nothing in this subchapter shall be construed as authorizing the execution or application of agreements requiring membership in a labor organization as a condition of employment in any State or Territory in which such execution or application is prohibited by State or Territorial law."],[0,"(c) Power of Board to decline jurisdiction of labor disputes; assertion of jurisdiction by State and Territorial courts"],[0,"(1) The Board, in its discretion, may, by rule of decision or by published rules adopted pursuant to subchapter II of chapter 5 of title 5, decline to assert jurisdiction over any labor dispute involving any class or category of employers, where, in the opinion of the Board, the effect of such labor dispute on commerce is not sufficiently substantial to warrant the exercise of its jurisdiction: Provided, That the Board shall not decline to assert jurisdiction over any labor dispute over which it would assert jurisdiction under the standards prevailing upon August 1, 1959."],[0,"(2) Nothing in this subchapter shall be deemed to prevent or bar any agency or the courts of any State or Territory (including the Commonwealth of Puerto Rico, Guam, and the Virgin Islands), from assuming and asserting jurisdiction over labor disputes over which the Board declines, pursuant to paragraph (1) of this subsection, to assert jurisdiction."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/164?type=usc&year=mostrecent&link-type=html"},"head":"§164. Construction of provisions","tname":"Labor","by":{"1":"1, 33","4":"5"}},{"t":"usc","label":"45 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/45/151","stext":{"head":"§151. Definitions; short title","paras":[[0,"When used in this chapter and for the purposes of this chapter—"],[0,"First. The term \"carrier\" includes any railroad subject to the jurisdiction of the Surface Transportation Board, any express company that would have been subject to subtitle IV of title 49, as of December 31, 1995,,1 and any company which is directly or indirectly owned or controlled by or under common control with any carrier by railroad and which operates any equipment or facilities or performs any service (other than trucking service) in connection with the transportation, receipt, delivery, elevation, transfer in transit, refrigeration or icing, storage, and handling of property transported by railroad, and any receiver, trustee, or other individual or body, judicial or otherwise, when in the possession of the business of any such \"carrier\": Provided, however, That the term \"carrier\" shall not include any street, interurban, or suburban electric railway, unless such railway is operating as a part of a general steam-railroad system of transportation, but shall not exclude any part of the general steam-railroad system of transportation now or hereafter operated by any other motive power. The Surface Transportation Board is authorized and directed upon request of the Mediation Board or upon complaint of any party interested to determine after hearing whether any line operated by electric power falls within the terms of this proviso. The term \"carrier\" shall not include any company by reason of its being engaged in the mining of coal, the supplying of coal to a carrier where delivery is not beyond the mine tipple, and the operation of equipment or facilities therefor, or in any of such activities."],[0,"Second. The term \"Adjustment Board\" means the National Railroad Adjustment Board created by this chapter."],[0,"Third. The term \"Mediation Board\" means the National Mediation Board created by this chapter."],[0,"Fourth. The term \"commerce\" means commerce among the several States or between any State, Territory, or the District of Columbia and any foreign nation, or between any Territory or the District of Columbia and any State, or between any Territory and any other Territory, or between any Territory and the District of Columbia, or within any Territory or the District of Columbia, or between points in the same State but through any other State or any Territory or the District of Columbia or any foreign nation."],[0,"Fifth. The term \"employee\" as used herein includes every person in the service of a carrier (subject to its continuing authority to supervise and direct the manner of rendition of his service) who performs any work defined as that of an employee or subordinate official in the orders of the Surface Transportation Board now in effect, and as the same may be amended or interpreted by orders hereafter entered by the Board pursuant to the authority which is conferred upon it to enter orders amending or interpreting such existing orders: Provided, however, That no occupational classification made by order of the Surface Transportation Board shall be construed to define the crafts according to which railway employees may be organized by their voluntary action, nor shall the jurisdiction or powers of such employee organizations be regarded as in any way limited or defined by the provisions of this chapter or by the orders of the Board."],[0,"The term \"employee\" shall not include any individual while such individual is engaged in the physical operations consisting of the mining of coal, the preparation of coal, the handling (other than movement by rail with standard railroad locomotives) of coal not beyond the mine tipple, or the loading of coal at the tipple."],[0,"Sixth. The term \"representative\" means any person or persons, labor union, organization, or corporation designated either by a carrier or group of carriers or by its or their employees, to act for it or them."],[0,"Seventh. The term \"district court\" includes the United States District Court for the District of Columbia; and the term \"court of appeals\" includes the United States Court of Appeals for the District of Columbia."],[0,"This chapter may be cited as the \"Railway Labor Act.\""]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/151?type=usc&year=mostrecent&link-type=html"},"head":"§151. Definitions; short title","tname":"Railroads","by":{"1":"1, 4, 33","3":"5, 58"}},{"t":"usc","label":"45 U.S.C. § 152","url":"https://www.law.cornell.edu/uscode/text/45/152","by":{"1":"1, 4, 33"}},{"t":"usc","label":"5 U.S.C. § 7103","url":"https://www.law.cornell.edu/uscode/text/5/7103","subs":["(a)(14)"],"by":{"1":"20"}},{"t":"usc","label":"5 U.S.C. § 7111","url":"https://www.law.cornell.edu/uscode/text/5/7111","subs":["(a)"],"by":{"1":"20"}},{"t":"case","label":"Board of Cnty. Comm’rs v. Umbehr","cite":"518 U.S. 668","y":1996,"id":"1995/94-1654","sc":1,"sum":"The Court held that the First Amendment's guarantee of freedom of speech shielded Umbehr, as a government employee, from termination due to things he might have said about the Board. Umbehr successfully proved that his criticisms of the Board preceded his termination and were the primary motivating factor behind its retaliatory termination of his contract.","sumSrc":"Oyez","by":{"2":"19, 20, 25","3":"22, 30, 53"}},{"t":"case","label":"Board of Ed. v. Compton","cite":"526 N.E.2d 149","y":1988,"court":"Ill.","url":"https://www.courtlistener.com/c/N.E.2d/526/149/","by":{"2":"53"}},{"t":"case","label":"Board of Ed. v. Mergens","cite":"496 U.S. 226","y":1990,"id":"1989/88-1597","sc":1,"sum":"The Court held that the Equal Access Act stopped Westside High School from prohibiting the formation of religious-based non-curricular student clubs.","sumSrc":"Oyez","by":{"2":"50"}},{"t":"case","label":"Borough of Duryea v. Guarnieri","cite":"564 U.S. 379","y":2011,"id":"2010/09-1476","sc":1,"sum":"The Court held that state and local government employees may not sue their employers for retaliation under the First Amendment's Petition Clause when they petition the government on matters of private concern.","sumSrc":"Oyez","by":{"2":"passim","3":"3, 22, 23, 28, 32, 34, 37, 44","5":"7, 15"}},{"t":"case","label":"City of Ontario v. Quon","cite":"560 U.S. 746","y":2010,"id":"2009/08-1332","sc":1,"sum":"The Court held that the city of Ontario's search of an employee's text messages did not violate his First Amendment rights because the search was not excessive in scope and was motivated by a legitimate work-related purpose.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"City of San Diego v. Roe","cite":"543 U.S. 77","y":2004,"id":"2004/03-1669","sc":1,"ar":1,"sum":"In a unanimous per curiam opinion, the Court held that firing Roe for his behavior and \"speech\" did not violate the First Amendment. Government employers, the Court wrote, could restrict their employees' speech in ways that would be unconstitutional if applied to the general public. But government employees had the right to speak on matters of public concern, such as on government policies of interest to the public.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Communications Workers v. Ector Cty. Hosp. Dist.","cite":"467 F.3d 427","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/467/427/","sum":"Upholding application of policy prohibiting hospital employee from wearing “Union Yes” pin at work.","sumSrc":"brief:2","by":{"2":"26"}},{"t":"case","label":"D’Agostino v. Baker","cite":"812 F.3d 240","y":2016,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/812/240/","by":{"2":"41"}},{"t":"case","label":"Engquist v. Or. Dep’t of Agric.","cite":"553 U.S. 591","y":2008,"id":"2007/07-474","sc":1,"sum":"The Court ruled 6-3 that the \"class-of-one\" theory of equal protection does not apply in the public employment context. The government enjoys significantly greater leeway in dealing with employees than it does with the public at large in its capacity as a regulator. Chief Justice John G. Roberts wrote the majority opinion.Justice John Paul Stevens authored a dissent.","sumSrc":"Oyez","by":{"2":"16, 19, 45","3":"20"}},{"t":"case","label":"Garcia v. San Antonio Metro. Transit Auth.","cite":"469 U.S. 528","y":1985,"id":"1983/82-1913","sc":1,"sum":"The Court ruled that Congress has the power under the Commerce Clause of the Constitution to extend the Fair Labor Standards Act to state and local governments.","sumSrc":"Oyez","by":{"2":"55"}},{"t":"case","label":"Gilpin v. AFSCME","cite":"875 F.2d 1310","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/875/1310/","by":{"2":"42","3":"55"}},{"t":"case","label":"Hill v. Service Emps. Int’l Union","cite":"850 F.3d 861","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/850/861/","ar":3,"by":{"2":"41"}},{"t":"case","label":"Hilton v. S.C. Pub. Railways Comm’n","cite":"502 U.S. 197","y":1991,"id":"1991/90-848","sc":1,"sum":"FELA creates a cause of action against a state-owned railroad, enforceable in state court.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"52","3":"50"}},{"t":"case","label":"Hohn v. United States","cite":"524 U.S. 236","y":1998,"id":"1997/96-8986","sc":1,"sum":"This decision overrules that portion of House v. Mayo, 324 U.S. 42, 44 (1945) (per curiam), which held that the Court lacks statutory certiorari jurisdiction to review denials of certificates of probable cause.","sumSrc":"Oyez","by":{"2":"53"}},{"t":"case","label":"Johnson v. California","cite":"543 U.S. 499","y":2005,"id":"2004/03-636","sc":1,"sum":"The Court held that prison racial-segregation policies are subject to strict scrutiny. The Court rejected the claim that because the policy was \"neutral\" - because all prisoners were \"equally\" segregated - the policy was not subject to strict scrutiny. Racial classifications must receive strict scrutiny even when they may be said to affect the races equally.","sumSrc":"Oyez","by":{"2":"50"}},{"t":"case","label":"Johnson v. United States","cite":"135 S. Ct. 2551","y":2015,"id":"2014/13-7120","sc":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"2":"55"}},{"t":"case","label":"Kelley v. Johnson","cite":"425 U.S. 238","y":1976,"id":"1975/74-1269","sc":1,"sum":"A county regulation limiting the length of county policemen's hair held not to violate any right guaranteed respondent policeman by the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"Keyishian v. Board of Regents","cite":"385 U.S. 589","y":1967,"id":"1966/105","sc":1,"sum":"The Court held that the provisions of the New York plan were defined in such uncertain terms that they infringed upon the constitutional rights of public servants.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Kimble v. Marvel Entm’t, LLC","cite":"135 S. Ct. 2401","y":2015,"id":"2014/13-720","sc":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"2":"51, 54, 56","3":"47, 48, 50, 56, 57"}},{"t":"case","label":"Knight v. Connecticut Dep’t of Pub. Health","cite":"275 F.3d 156","y":2001,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/275/156/","sum":"Upholding application of policy preventing interpreters from proselytizing on the job.","sumSrc":"brief:2","by":{"2":"26–37"}},{"t":"case","label":"Lehnert v. Ferris Faculty Ass’n","cite":"881 F.2d 1388","y":1989,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/881/1388/","by":{"2":"30"}},{"t":"case","label":"Minn. State Bd. for Cmty. Colls. v. Knight","cite":"465 U.S. 271","y":1984,"id":"1983/82-898","sc":1,"sum":"The \"meet and confer\" provisions do not violate appellees' constitutional rights.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"passim","3":"27, 39, 43, 57","5":"13, 14"}},{"t":"case","label":"NASA v. Nelson","cite":"562 U.S. 134","y":2011,"id":"2010/09-530","sc":1,"sum":"The Court held that the government's extended background checks for federal employees under the Bush administration's antiterrorism initiative did not violate an employee's constitutional right to privacy.","sumSrc":"Oyez","by":{"2":"16, 19, 29, 57","3":"20, 30"}},{"t":"case","label":"NLRB v. General Motors Corp.","cite":"373 U.S. 734","y":1963,"id":"1962/404","sc":1,"sum":"An \"agency shop\" arrangement, which leaves union membership optional with the employees but requires that, as a condition of continued employment, nonunion employees pay to the union sums equal to the initiation fees and periodic dues paid by union members, does not in itself constitute an unfair labor practice under § 8 (a) (3) of the National Labor Relations Act and is not prohibited by § 7 or § 8. In a State …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37, 42","3":"5"}},{"t":"case","label":"O’Connor v. Ortega","cite":"480 U.S. 709","y":1987,"id":"1986/85-530","sc":1,"sum":"In a 5-to-4 decision, the Court held that the search did not violate the Fourth Amendment. The Court held that \"the realities of the workplace\" made some expectations of privacy among public employees unreasonable when the intrusion was by a supervisor rather than a law enforcement official.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Pearson v. Callahan","cite":"555 U.S. 223","y":2009,"id":"2008/07-751","sc":1,"sum":"A case in which the Court overturned its previous decision in Saucier v. Katz, which prescribed a rigid test for government qualified immunity claims, and held that inquiries should be at the discretion of the lower courts.","sumSrc":"Oyez","by":{"2":"54"}},{"t":"case","label":"Perry v. Sindermann","cite":"408 U.S. 593","y":1972,"id":"1971/70-36","sc":1,"sum":"The Court affirmed the Fifth Circuit and held that Sindermann was entitled to a full trial in federal District Court and a hearing before the Board of Regents. The Court acknowledged that Sindermann did not have a contractual or tenure-based right to continued employment by Odessa Junior College.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Randall v. Sorrell","cite":"548 U.S. 230","y":2006,"id":"2005/04-1528","sc":1,"sum":"The opinion by Justice Stephen Breyer held that the Court should let stand the Buckley decision and its invalidation of expenditure limits. Vermont's argument that such limits prevent candidates from spending too much time fund-raising was deemed irrelevant because it was \"perfectly obvious\" and would not have changed the result in Buckley .","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"United Public Workers of America v. Mitchell","cite":"330 U.S. 75","y":1947,"id":"1940-1955/330us75","sc":1,"sum":"The Court held that the Hatch Act does not unconstitutionally restrict the rights of employees of the federal government.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"United States ex rel. Texas Portland Cement Co. v. McCord","cite":"233 U.S. 157","y":1914,"id":"scdb/1913-178","sc":1,"sum":"When the purpose of Congress is stated in such plain terms that there is no uncertainty, and no construction is required, it is unnecessary to inquire into the motives which induced the legislation. The only province of the courts in such a case is to enforce the statute in accordance with its terms.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"14","3":"14, 16, 17"}},{"t":"case","label":"United States v. Donnelly’s Estate","cite":"397 U.S. 286","y":1970,"id":"1969/104","sc":1,"sum":"The Government's tax lien was properly filed in-the District Court and was thus entitled to priority. Any reliance that the Carlsons may have placed on the lower courts' construction of § 3672 which the Government had never accepted and which this Court rejected in United States v. Union Central Life Ins. Co.,","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"52"}},{"t":"case","label":"United States v. IBM Corp.","cite":"517 U.S. 843","y":1996,"id":"1995/95-591","sc":1,"sum":"Announced by Justice Clarence Thomas, the Court ruled the tax did violate the Export Clause and was therefore unconstitutional.","sumSrc":"Oyez","by":{"2":"51","3":"17, 52"}},{"t":"case","label":"Village of Willowbrook v. Olech","cite":"528 U.S. 562","y":2000,"id":"1999/98-1288","sc":1,"sum":"The Court held that Olech's allegations were sufficient to state a claim for relief under traditional equal protection analysis. \"Our cases have recognized successful equal protection claims brought by a 'class of one,' where the plaintiff alleges that she has been intentionally treated differently from others similarly situated and that there is no rational basis for the difference in treatment,\" stated the unanimous, unsigned opinion.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Waters v. Churchill","cite":"511 U.S. 661","y":1994,"id":"1993/92-1450","sc":1,"sum":"A four-justice plurality held that government workers cannot be dismissed or otherwise punished for their words unless the employer has a reasonable basis for believing that the speech either was disruptive or involved a matter of purely private concern, outside the scope of the First Amendment's protection.","sumSrc":"Oyez","by":{"2":"16, 20"}},{"t":"usc","label":"29 U.S.C. § 159","url":"https://www.law.cornell.edu/uscode/text/29/159","subs":["(a)"],"by":{"2":"37"}},{"t":"case","label":"Adler v. Board of Educ.","cite":"342 U.S. 485","y":1952,"id":"scdb/1951-050","sc":1,"sum":"Osmond K. Fraenkel argued the, cause foi appellants. With him on the brief was Arthur Garfield Hays.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"18"}},{"t":"case","label":"Air Line Pilots Ass’n v. Miller","cite":"523 U.S. 866","y":1998,"id":"1997/97-428","sc":1,"sum":"Announced by Justice Ruth Bader Ginsburg, the Court ruled the nonunion pilots cannot be forced to go through arbitration. \"Unless they agree to the procedure, agency-fee objectors may not be required to exhaust an arbitration remedy before bringing their claims in federal court,\" wrote Ginsburg.","sumSrc":"Oyez","by":{"3":"7"}},{"t":"case","label":"Arizona v. Rumsey","cite":"467 U.S. 203","y":1984,"id":"1983/83-226","sc":1,"sum":"The Double Jeopardy Clause prohibits Arizona from sentencing respondent to death. …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"52"}},{"t":"case","label":"Brown v. Entertainment Merchants Ass’n","cite":"564 U.S. 786","y":2011,"id":"2010/08-1448","sc":1,"sum":"The Court held that video games, including violent ones, are protected speech under the First Amendment.","sumSrc":"Oyez","by":{"3":"2"}},{"t":"case","label":"Brown v. Glines","cite":"444 U.S. 348","y":1980,"id":"1979/78-1006","sc":1,"sum":"The regulations are not invalid on their face.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"41"}},{"t":"case","label":"Christian Legal Soc’y Chapter of Univ. of California v. Martinez","cite":"561 U.S. 661","y":2010,"id":"2009/08-1371","sc":1,"sum":"The Court held that a college's mandate requiring all officially-recognized student organizations be inclusive and welcoming to all students did not violate a group of Christian students' First Amendment rights when the college refused to recognize a student group that required all members to sign a statement of Christian beliefs for membership.","sumSrc":"Oyez","by":{"3":"58"}},{"t":"case","label":"District of Columbia v. Heller","cite":"554 U.S. 570","y":2008,"id":"2007/07-290","sc":1,"ar":1,"sum":"The Court found a District of Columbia law strictly regulating gun ownership to be unconstitutional.","sumSrc":"Oyez","by":{"3":"19, 51"}},{"t":"case","label":"Erznoznik v. City of Jacksonville","cite":"422 U.S. 205","y":1975,"id":"1974/73-1942","sc":1,"sum":"The Court struck down the Jacksonville ordinance. While individuals did have a right to not be exposed to offensive films, the ordinance singled out \"some kinds of speech on the ground that they are more offensive than others,\" Justice Lewis F. Powell, Jr. wrote for the majority.","sumSrc":"Oyez","by":{"3":"54"}},{"t":"case","label":"Friedrichs v. California Teachers Ass’n","cite":"136 S. Ct. 1083","y":2016,"id":"2015/14-915","sc":1,"sum":"A case in which the Court will determine whether the California agency shop arrangements and opt-out requirements for union relationships violate the First Amendment.","sumSrc":"Oyez","by":{"3":"57"}},{"t":"case","label":"Gentile v. State Bar of Nevada","cite":"501 U.S. 1030","y":1991,"id":"1990/89-1836","sc":1,"sum":"The judgment is reversed. 106 Nev. 60, 787 P. 2d 386, reversed. JUSTICE KENNEDY delivered the opinion of the Court with respect to Parts III and VI, concluding that, as interpreted by the Nevada Supreme Court, Rule 177 is void for vagueness. Its safe harbor provision, Rule 177(3), misled Gentile into thinking that he could give his press conference without fear of discipline. Given the Rule's grammatical structure …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"41"}},{"t":"case","label":"Grupo Dataflux v. Atlas Global Grp., L.P.","cite":"541 U.S. 567","y":2004,"id":"2003/02-1689","sc":1,"sum":"In a 5-to-4 decision written by Justice Antonin Scalia, the Court ruled that allowing diversity jurisdiction to change after a case is filed would create uncertainty and expensive litigation that dealt with jurisdiction rather than the merits of the case. \"Uncertainty regarding the question of jurisdiction is particularly undesirable, and collateral litigation on the point particularly wasteful,\" wrote Justice Scalia. \"The stability provided by our time tested rule (of requiring diversity at the time of filing) weighs heavily against the approval of any new deviation.\".","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Lathrop v. Donohue","cite":"367 U.S. 820","y":1961,"id":"1960/200","sc":1,"ar":1,"sum":"Acting in accordance with an Act of the State Legislature, the Supreme Court of Wisconsin promulgated rules and bylaws creating an integrated State Bar and requiring all lawyers practicing in the State to be members thereof and to pay annual dues of $15. Appellant paid his dues under protest and sued for a refund, claiming that the State Bar engaged in political activities which he opposed, and that by coercing him …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"40"}},{"t":"case","label":"McAuliffe v. City of New Bedford","cite":"29 N.E. 517","y":1892,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./29/517/","by":{"3":"2"}},{"t":"case","label":"Melendez-Diaz v. Massachusetts","cite":"557 U.S. 305","y":2009,"id":"2008/07-591","sc":1,"sum":"The Court found that a state forensic analyst's lab report prepared for use in a criminal prosecution is subject to the demands of the Sixth Amendment Confrontation Clause.","sumSrc":"Oyez","by":{"3":"59"}},{"t":"case","label":"Morse v. Frederick","cite":"551 U.S. 393","y":2007,"id":"2006/06-278","sc":1,"sum":"The Court found an Alaska public school principal had the right to suspend a student for holding up a \"BONG HiTS 4 JESUS\" banner at a school-sponsored event.","sumSrc":"Oyez","by":{"3":"41"}},{"t":"case","label":"NLRB v. Jones & Laughlin Steel Corp.","cite":"301 U.S. 1","y":1937,"id":"1900-1940/301us1","sc":1,"sum":"The Court found that the Commerce Clause gave the government the right to regulate labor-management disputes.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Obergefell v. Hodges","cite":"135 S. Ct. 2584","y":2015,"id":"2014/14-556","sc":1,"sum":"The Court held that the Fourteenth Amendment requires states to license and recognize same-sex marriage.","sumSrc":"Oyez","by":{"3":"19, 20, 53","4":"2, 13, 14"}},{"t":"case","label":"Perry Educ. Ass’n v. Perry Local Educators’ Ass’n","cite":"460 U.S. 37","y":1983,"id":"1982/81-896","sc":1,"sum":"Justice Byron White delivered the opinion of a 5-4 court. The school board chose to grant exclusive access to the official teachers union in order to facilitate a collective-bargaining agreement. It did not act to suppress the speech of rival teachers unions. The school board entrusted PEA with obligations as the sole representative of teachers that would require the use of the mail system.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"Phillips Petroleum Co. v. Shutts","cite":"472 U.S. 797","y":1985,"id":"1984/84-233","sc":1,"sum":"During the 1970's, petitioner produced or purchased natural gas from leased land located in 11 States. Respondents, royalty owners possessing rights to leases from which petitioner produced the gas, brought a class action against petitioner in a Kansas state court, seeking to recover interest on royalty payments that had been delayed by petitioner. The trial court certified a class consisting of 33,000 royalty …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"58"}},{"t":"case","label":"Sabri v. United States","cite":"541 U.S. 600","y":2004,"id":"2003/03-44","sc":1,"sum":"The Court held that Article I of the Constitution allows Congress to prohibit bribery of organizations that distribute federal funds. The Justices found that the Spending Clause authorizes Congress to spend money for the general welfare, and that the Necessary and Proper Clause authorizes it to take any reasonable steps to prevent such money from being misspent.","sumSrc":"Oyez","by":{"3":"54"}},{"t":"case","label":"Smith v. Arkansas State Highway Emps.","cite":"441 U.S. 463","y":1979,"id":"1978/78-1223","sc":1,"sum":"The Arkansas State Highway Commission's refusal to consider employee grievances when filed by the union rather than directly by an employee of the State Highway Department does not violate the First Amendment. Even assuming that the Commission's procedure would constitute an unfair labor practice if the Commission were subject to the same labor laws applicable to private employers and that its procedure tends to …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"23, 24"}},{"t":"case","label":"Snepp v. United States","cite":"444 U.S. 507","y":1980,"id":"1979/78-1871","sc":1,"sum":"The Court upheld the lower court's ruling and agreed that Snepp had breached the \"constructive trust\" between him and the government. That was especially significant in this case since this type of violation by a former agent \"impairs the CIA's ability to perform its statutory duties\" and potentially jeopardizes the safety of current government operatives and Snepp himself.","sumSrc":"Oyez","by":{"3":"3, 56"}},{"t":"case","label":"United States v. Salerno","cite":"481 U.S. 739","y":1987,"id":"1986/86-87","sc":1,"sum":"The Court held that the Act was constitutional because when the government's interest in protecting the community outweighs individual liberty, pre-trial detention can be \"a potential solution to a pressing societal problem.\" The Act only applied to a specific list of serious offenses, placed heavy burdens on the government to prove that the arrestee posed significant threats to others, and did not prevent the accused from enjoying a speedy trial.","sumSrc":"Oyez","by":{"3":"46"}},{"t":"case","label":"Vasquez v. Hillery","cite":"474 U.S. 254","y":1986,"id":"1985/84-836","sc":1,"sum":"The Court held that Hillery was allowed to pursue his claim in federal court because the district court was within its power to request additional evidence that did not fundamentally alter the legal claim that the state courts already considered.","sumSrc":"Oyez","by":{"3":"47"}},{"t":"case","label":"Washington State Grange v. Washington State Republican Party","cite":"552 U.S. 442","y":2008,"id":"2007/06-713","sc":1,"sum":"The Court reversed the Ninth Circuit's ruling and held the party affiliation provision constitutional. Writing for the majority, Justice Clarence Thomas explained that the state law never referred to the candidates as nominees of any particular party.","sumSrc":"Oyez","by":{"3":"53"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"39"}},{"t":"usc","label":"29 U.S.C. § 141","url":"https://www.law.cornell.edu/uscode/text/29/141","stext":{"head":"§141. Short title; Congressional declaration of purpose and policy","paras":[[0,"(a) This chapter may be cited as the \"Labor Management Relations Act, 1947\"."],[0,"(b) Industrial strife which interferes with the normal flow of commerce and with the full production of articles and commodities for commerce, can be avoided or substantially minimized if employers, employees, and labor organizations each recognize under law one another's legitimate rights in their relations with each other, and above all recognize under law that neither party has any right in its relations with any other to engage in acts or practices which jeopardize the public health, safety, or interest."],[0,"It is the purpose and policy of this chapter, in order to promote the full flow of commerce, to prescribe the legitimate rights of both employees and employers in their relations affecting commerce, to provide orderly and peaceful procedures for preventing the interference by either with the legitimate rights of the other, to protect the rights of individual employees in their relations with labor organizations whose activities affect commerce, to define and proscribe practices on the part of labor and management which affect commerce and are inimical to the general welfare, and to protect the rights of the public in connection with labor disputes affecting commerce."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/141?type=usc&year=mostrecent&link-type=html"},"head":"§141. Short title; Congressional declaration of purpose and policy","tname":"Labor","by":{"3":"35, 36","4":"5"}},{"t":"reg","label":"5 C.F.R. § 734.306","url":"https://www.ecfr.gov/current/title-5/section-734.306","by":{"3":"24"}},{"t":"case","label":"McDaniel v. Paty","cite":"435 U.S. 618","y":1978,"id":"1977/76-1427","sc":1,"sum":"The Court held that the statute made the ability to exercise civil rights conditional on the surrender of religious rights and therefore violated the First Amendment protection of the free exercise of religion as applied to the states by the Fourteenth Amendment.","sumSrc":"Oyez","by":{"4":"16"}},{"t":"case","label":"Roe v. Wade","cite":"410 U.S. 113","y":1973,"id":"1971/70-18","sc":1,"sum":"A case in which the Court struck down several Texas laws that criminalized abortion, holding that laws that impose an undue burden on a woman’s right to seek an abortion violate her fundamental right to privacy under the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"4":"2, 13"}},{"t":"case","label":"Walz v. Tax Comm’n","cite":"397 U.S. 664","y":1970,"id":"1969/135","sc":1,"sum":"In a 7-to-1 decision, the Court held that the exemptions did not violate the Establishment Clause. The Court held that the purpose of the exemptions was to neither advance nor inhibit religion; no one particular church or religious group had been singled out to receive tax exempt status.","sumSrc":"Oyez","by":{"4":"16"}},{"t":"usc","label":"29 U.S.C. § 169","url":"https://www.law.cornell.edu/uscode/text/29/169","by":{"4":"8"}},{"t":"reg","label":"29 C.F.R. § 1605.2","url":"https://www.ecfr.gov/current/title-29/section-1605.2","by":{"4":"8"}},{"t":"case","label":"Cal. Motor Transp. v. Trucking Unlimited","cite":"404 U.S. 508","y":1972,"id":"1971/70-92","sc":1,"sum":"While any carrier has the right of access to administrative agencies and courts to defeat applications of competitors for certificates as highway carriers, and its purpose to eliminate an applicant as a competitor may be implicit in such opposition, its First Amendment rights are not immunized from regulation when they are used as an integral part of conduct violative of the antitrust laws. If the allegations that …","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"4"}},{"t":"case","label":"Givhan v. W. Line Sch. Dist.","cite":"439 U.S. 410","y":1979,"id":"1978/77-1051","sc":1,"sum":"A public employee does not forfeit his First Amendment protection against governmental abridgment of freedom of speech when he arranges to communicate privately with his employer rather than to express his views publicly.","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"4"}},{"t":"case","label":"Miami Herald Publ’g Co. v. Tornillo","cite":"418 U.S. 241","y":1974,"id":"1973/73-797","sc":1,"sum":"The Court reversed the Supreme Court of Florida and held that Florida's \"right to reply\" statute violated the freedom of press found in the First Amendment. In an opinion written by Chief Justice Warren E. Burger, the Court recognized the risks posed to the \"true marketplace of ideas\" by media consolidation and barriers to entry in the newspaper industry.","sumSrc":"Oyez","by":{"5":"6"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"5":"23"}},{"t":"case","label":"United States v. Williams","cite":"504 U.S. 36","y":1992,"id":"1991/90-1972","sc":1,"sum":"Respondent Williams was indicted by a federal grand jury for alleged violations of 18 U. S. C. § 1014. On his motion, the District Court ordered the indictment dismissed without prejudice because the Government had failed to fulfill its obligation under Circuit precedent to present \"substantial exculpatory evidence\" to the grand jury. Following that precedent, the Court of Appeals affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"2"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"5":"1"}},{"t":"usc","label":"28 U.S.C. § 1343","url":"https://www.law.cornell.edu/uscode/text/28/1343","subs":["(a)(3)"],"by":{"5":"1"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"5":"2"}}]};